-- Generated by drizzle-kit (`--name session_rules`), then EDITED BY HAND
-- (Phase 4 step 1a, decided with the person 2026-10-15). Three edits, each
-- marked below:
--   1. the status column's default is dropped BEFORE the old type (the
--      default 'pending' depends on it — drizzle-kit dropped it after);
--   2. old rows are given the new meanings while the column is plain text;
--   3. the backfill runs BEFORE the CHECKs and unique indexes, which test
--      every existing row when they are created.
-- Run by the tables' owner, so no audit entry: a migration has no user to
-- name (audit_logs.performed_by is NOT NULL) — this file is the record, as
-- for 0032, 0034, 0035 and 0036. In practice only test databases hold rows
-- the backfill changes: the dev seed writes completed sessions only.
CREATE TYPE "public"."session_end_reason" AS ENUM('pain', 'illness', 'no_time', 'other', 'not_finished_in_time', 'program_closed');--> statement-breakpoint
-- EDITED BY HAND (1): moved up from after the type change.
ALTER TABLE "sessions" ALTER COLUMN "status" DROP DEFAULT;--> statement-breakpoint
ALTER TABLE "sessions" ALTER COLUMN "status" SET DATA TYPE text;--> statement-breakpoint
-- EDITED BY HAND (2): 'pending' has no value in the new type. A row exists
-- only once the patient started (decisions §5, 2026-10-09), so an old
-- pending row was a started session: in_progress.
UPDATE "sessions" SET "status" = 'in_progress' WHERE "status" = 'pending';--> statement-breakpoint
DROP TYPE "public"."session_status";--> statement-breakpoint
CREATE TYPE "public"."session_status" AS ENUM('in_progress', 'completed', 'incomplete', 'skipped');--> statement-breakpoint
ALTER TABLE "sessions" ALTER COLUMN "status" SET DATA TYPE "public"."session_status" USING "status"::"public"."session_status";--> statement-breakpoint
ALTER TABLE "sessions" ADD COLUMN "ended_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "sessions" ADD COLUMN "end_reason" "session_end_reason";--> statement-breakpoint
ALTER TABLE "sessions" ADD COLUMN "end_note" varchar(500);--> statement-breakpoint
ALTER TABLE "sessions" ADD COLUMN "pain_before" smallint;--> statement-breakpoint
ALTER TABLE "sessions" ADD COLUMN "pain_after" smallint;--> statement-breakpoint
ALTER TABLE "sessions" ADD COLUMN "mobility_after" smallint;--> statement-breakpoint
-- EDITED BY HAND (3): the backfill. Before 2026-10-15 any status could
-- follow any other, so old rows can have any combination. Each step gives
-- them the shape their status now requires:
--   a. 'skipped' used to mean "not done", started or not. A skipped row with
--      anything recorded — a start, a duration, feedback — was started:
--      that is now 'incomplete'.
UPDATE "sessions" SET "status" = 'incomplete'
  WHERE "status" = 'skipped'
    AND ("started_at" IS NOT NULL OR "total_duration_in_seconds" IS NOT NULL OR "session_feedback" IS NOT NULL);--> statement-breakpoint
--   b. Every status but a skip has a start. An old row moved straight from
--      pending to completed never got one: its creation moment
--      (scheduled_date, set when the row was inserted) is the best known.
UPDATE "sessions" SET "started_at" = "scheduled_date"
  WHERE "started_at" IS NULL AND "status" <> 'skipped';--> statement-breakpoint
--   c. A session that isn't completed has no completion moment (one sent
--      back from completed kept its stale completed_at). One that ended
--      otherwise gets an end moment — the latest one known — and a reason:
--      'other', since none was ever asked.
UPDATE "sessions" SET
    "ended_at" = COALESCE("completed_at", "started_at", "scheduled_date"),
    "end_reason" = 'other'
  WHERE "status" IN ('incomplete', 'skipped');--> statement-breakpoint
UPDATE "sessions" SET "completed_at" = NULL WHERE "status" <> 'completed';--> statement-breakpoint
--   d. One open session per program (the index below): the newest stays
--      open, older ones are closed the way the app now closes them.
UPDATE "sessions" s SET
    "status" = 'incomplete',
    "ended_at" = now(),
    "end_reason" = 'not_finished_in_time'
  WHERE s."status" = 'in_progress'
    AND EXISTS (
      SELECT 1 FROM "sessions" newer
      WHERE newer."assigned_program_id" = s."assigned_program_id"
        AND newer."status" = 'in_progress'
        AND newer."id" > s."id"
    );--> statement-breakpoint
--   e. One skip per program per day (the index below): the first stays a
--      skip; a later duplicate (only possible through the old API) becomes
--      'incomplete', the one other shape a not-done row can take — given its
--      creation moment as its start, since that shape requires one.
UPDATE "sessions" s SET
    "status" = 'incomplete',
    "started_at" = s."scheduled_date"
  WHERE s."status" = 'skipped'
    AND EXISTS (
      SELECT 1 FROM "sessions" earlier
      WHERE earlier."assigned_program_id" = s."assigned_program_id"
        AND earlier."local_date" = s."local_date"
        AND earlier."status" = 'skipped'
        AND earlier."id" < s."id"
    );--> statement-breakpoint
CREATE UNIQUE INDEX "sessions_one_open_per_program" ON "sessions" USING btree ("assigned_program_id") WHERE "sessions"."status" = 'in_progress';--> statement-breakpoint
CREATE UNIQUE INDEX "sessions_one_skip_per_day" ON "sessions" USING btree ("assigned_program_id","local_date") WHERE "sessions"."status" = 'skipped';--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_status_moments" CHECK (CASE "sessions"."status"
        WHEN 'in_progress' THEN "sessions"."started_at" IS NOT NULL AND "sessions"."completed_at" IS NULL AND "sessions"."ended_at" IS NULL
        WHEN 'completed' THEN "sessions"."started_at" IS NOT NULL AND "sessions"."completed_at" IS NOT NULL AND "sessions"."ended_at" IS NULL
        WHEN 'incomplete' THEN "sessions"."started_at" IS NOT NULL AND "sessions"."completed_at" IS NULL AND "sessions"."ended_at" IS NOT NULL
        WHEN 'skipped' THEN "sessions"."started_at" IS NULL AND "sessions"."completed_at" IS NULL AND "sessions"."ended_at" IS NOT NULL
      END);--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_end_reason_matches_status" CHECK (("sessions"."end_reason" IS NOT NULL) = ("sessions"."status" IN ('incomplete', 'skipped'))
        AND ("sessions"."status" <> 'skipped' OR "sessions"."end_reason" IN ('pain', 'illness', 'no_time', 'other')));--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_end_note_needs_reason" CHECK ("sessions"."end_note" IS NULL OR "sessions"."end_reason" IS NOT NULL);--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_check_out_when_ended" CHECK (("sessions"."pain_after" IS NULL AND "sessions"."mobility_after" IS NULL)
        OR "sessions"."status" IN ('completed', 'incomplete'));--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_skip_records_no_work" CHECK ("sessions"."status" <> 'skipped' OR (
        "sessions"."total_duration_in_seconds" IS NULL
        AND "sessions"."session_feedback" IS NULL
        AND ("sessions"."pain_before" IS NULL OR "sessions"."end_reason" = 'pain')
      ));--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_pain_before_range" CHECK ("sessions"."pain_before" IS NULL OR "sessions"."pain_before" BETWEEN 0 AND 10);--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_pain_after_range" CHECK ("sessions"."pain_after" IS NULL OR "sessions"."pain_after" BETWEEN 0 AND 10);--> statement-breakpoint
ALTER TABLE "sessions" ADD CONSTRAINT "sessions_mobility_after_range" CHECK ("sessions"."mobility_after" IS NULL OR "sessions"."mobility_after" BETWEEN 0 AND 10);